input.command:
node << 'EOF'
const { chromium } = require("<HOME>/git/cronex/demo/node_modules/playwright-core");
const exe = "<HOME>/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome";
const url = "file://<WORKSPACE>/index.html";
(async () => {
  const browser = await chromium.launch({ executablePath: exe, args: ["--no-sandbox"] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  await page.goto(url);
  await page.waitForTimeout(900);
  await page.screenshot({ path: "<TMP>/ramen-desktop.png" });

  const before = await page.evaluate(() => ({
    mx: getComputedStyle(document.documentElement).getPropertyValue("--mx"),
    heat: getComputedStyle(document.documentElement).getPropertyValue("--heat"),
    anim: getComputedStyle(document.querySelector(".wisp")).animationName,
    transform: document.getElementById("steamNear").getAttribute("transform")
  }));
  const bowl = await page.locator(".bowl").boundingBox();
  await page.mouse.move(bowl.x + bowl.width * 0.72, bowl.y + bowl.height * 0.35);
  await page.waitForTimeout(400);
  const after = await page.evaluate(() => ({
    mx: getComputedStyle(document.documentElement).getPropertyValue("--mx").trim(),
    my: getComputedStyle(document.documentElement).getPropertyValue("--my").trim(),
    heat: getComputedStyle(document.documentElement).getPropertyValue("--heat").trim(),
    steam: document.getElementById("steamNear").getAttribute("transform"),
    sheen: document.getElementById("brothSheen").getAttribute("transform")
  }));
  await page.mouse.click(bowl.x + bowl.width * 0.5, bowl.y + bowl.height * ((496-330)/500));
  await page.waitForTimeout(80);
  const rip = await page.evaluate(() => document.querySelector("#mist").width);
  await page.screenshot({ path: "<TMP>/ramen-hover.png" });

  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(300);
  await page.screenshot({ path: "<TMP>/ramen-mobile.png" });

  const page2 = await browser.newPage({ viewport: { width: 1440, height: 900 }, reducedMotion: "reduce" });
  await page2.goto(url);
  await page2.waitForTimeout(300);
  const reduced = await page2.evaluate(() => ({
    anim: getComputedStyle(document.querySelector(".wisp")).animationName,
    mx: getComputedStyle(document.documentElement).getPropertyValue("--mx").trim(),
    mist: getComputedStyle(document.getElementById("mist")).display
  }));
  const b2 = await page2.locator(".bowl").boundingBox();
  await page2.mouse.move(b2.x + 40, b2.y + 40);
  await page2.waitForTimeout(200);
  const reducedAfter = await page2.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue("--mx").trim());
  await page2.screenshot({ path: "<TMP>/ramen-reduce.png" });

  console.log(JSON.stringify({ errors, before, after, reduced, reducedAfter, bowl }, null, 2));
  await browser.close();
})();
EOF

